"Siemens"}]}, "vulnerabilities": [{"cve": "CVE-2025-47809", "cwe": {"id": "CWE-272", "name": "Least Privilege Violation"}, "notes": [{"category": "description", "text": "Wibu CodeMeter before 8.30a sometimes allows privilege escalation immediately after installation (before a logoff or reboot). For exploitation, there must have been an unprivileged installation with UAC, and the CodeMeter Control Center component must be installed, and the CodeMeter Control Center component must not have been restarted. In this scenario, the local user can navigate from Import License to a privileged instance of Windows Explorer.", "title": "CVE Description"}], "product_status": {"known_affected": ["CSAFPID-0001", "CSAFPID-0002", "CSAFPID-0003", "CSAFPID-0004"]}, "references": [{"category": "external", "summary": "www.cve.org", "url": "https://www.cve.org/CVERecord?id=CVE-2025-47809"}, {"category": "external", "summary": "cwe.mitre.org", "url": "https://cwe.mitre.org/data/definitions/272.html"}, {"category": "external", "summary": "www.first.org", "url": "https://www.first.org/cvss/calculator/3.1#CVSS:3.1/AV:L/AC:L/PR:H/UI:N/S:C/C:H/I:H/A:H"}], "remediations": [{"category": "vendor_fix", "details": "Update to V3.18 P032 or later version", "product_ids": ["CSAFPID-0002"], "url": "https://support.industry.siemens.com/cs/ww/en/view/109994004/"}, {"category": "vendor_fix", "details": "Update to V3.19 P020 or later version", "product_ids": ["CSAFPID-0003"], "url": "https://support.industry.siemens.com/cs/ww/en/view/109989640/"}, {"category": "vendor_fix", "details": "Update to V3.20 P008 or later version", "product_ids": ["CSAFPID-0004"], "url": "https://support.industry.siemens.com/cs/ww/en/view/109990967/"}, {"category": "vendor_fix", "details": "Update to V5.0 SP2 or later version", "product_ids": ["CSAFPID-0001"], "url": "https://support.industry.siemens.com/cs/ww/en/view/110004810/"}], "scores": [{"cvss_v3": {"baseScore": 8.2, "baseSeverity": "HIGH", "vectorString": "CVSS:3.1/AV:L/AC:L/PR:H/UI:N/S:C/C:H/I:H/A:H", "version": "3.1"}, "products": ["CSAFPID-0001", "CSAFPID-0002", "CSAFPID-0003", "CSAFPID-0004"]}], "title": "CVE-2025-47809"}]}
